	{"Step08", "stepstone", "Paths", 123.71, 12.32, -13.26, 0, 6.5, 1, 6.5, {Order = 8}},
	{"SpawnLocation", "spawn", "Spawn", 0, 1.2, 140, 0, 10, 1, 10, {}},
